if ($_SERVER['REQUEST_METHOD']==='POST') { admin_csrf_check(); $email=trim((string)($_POST['email']??'')); $password=(string)($_POST['password']??''); $stmt=$pdo->prepare("SELECT id,full_name,email,password_hash,role,status FROM users WHERE email=? LIMIT 1"); $stmt->execute([$email]); $user=$stmt->fetch(); if ($user && $user['role']==='admin' && $user['status']==='active' && password_verify($password,$user['password_hash'])) { session_regenerate_id(true); $_SESSION['admin_id']=(int)$user['id']; $_SESSION['admin_role']='admin'; $pdo->prepare('UPDATE users SET last_login_at=NOW() WHERE id=?')->execute([(int)$user['id']]); redirect('index.php'); } $error='Invalid credentials or this account does not have active administrator access.'; }
