ime first-admin setup.</div><a href="setup.php" class="btn btn-primary w-100">Set up first administrator</a><?php else: ?><form method="post"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><div class="mb-3"><label class="form-label" for="email">Email address</label><input class="form-control" type="email" id="email" name="email" required autocomplete="username" maxlength="190"></div><div class="mb-3"><label class="form-label" for="password">Password</label><input class="form-control" type="password" id="password" name="password" required autocomplete="current-password"></div><button class="btn btn-primary w-100" type="submit">Sign in</button></form><?php endif; ?><p class="text-secondary small mt-4 mb-0">Local development panel. Use HTTPS and additional hardening before public deployment.</p></main><script src="../assets/js/app.js"></script></body></html>
